use serde::{Deserialize, Serialize};
use std::collections::HashMap;

fn main () -> Result < () > { println ! ("🚀 Booting SPARQL Engine with PetGraph") ; println ! ("=====================================\n") ; let mut engine = SparqlEngine :: new () ; println ! ("📚 Loading knowledge base...") ; engine . load_knowledge_base ("rustc_lmdfb_knowledge_base.owl") ? ; println ! ("\n🔍 Running SPARQL Queries:") ; let query1 = sparql_select ! (s has_type RustcComponent) ; println_sparql ! ("1" , query1) ; let components = engine . select_where ("?s rdf:type lmdfb:RustcComponent") ; println ! ("   Found {} components" , components . len ()) ; let query2 = sparql_select ! (s has_property hasLevel as level) ; println_sparql ! ("2" , query2) ; let levels = engine . select_where ("?s lmdfb:hasLevel ?level") ; println ! ("   Found {} nodes with levels" , levels . len ()) ; println ! ("\n3. SELECT ?s ?pattern WHERE {{ ?s lmdfb:hasSemanticPattern ?pattern }}") ; let patterns = engine . select_where ("?s lmdfb:hasSemanticPattern ?pattern") ; println ! ("   Found {} semantic patterns" , patterns . len ()) ; engine . analyze_graph_structure () ; println ! ("\n✅ SPARQL Engine Ready!") ; println ! ("   Graph loaded with {} nodes and {} edges" , engine . graph . node_count () , engine . graph . edge_count ()) ; println ! ("   Ready for complex graph queries and analysis!") ; Ok (()) }